add_filter( 'woocommerce_checkout_fields', 'perfectpixel_length_limits_attributes', 9999 );
add_action( 'woocommerce_checkout_process', 'perfectpixel_length_limits_validate' );

/**
 * Field key => [ min, max ] (0 = no limit).
 */
function perfectpixel_length_limits() {
	return array(
		'billing_company'  => array( 0, 15 ),
		'billing_postcode' => array( 5, 5 ),
		'billing_phone'    => array( 10, 15 ),
	);
}

function perfectpixel_length_limits_attributes( $fields ) {
	foreach ( perfectpixel_length_limits() as $key => $limit ) {
		foreach ( $fields as $group => $group_fields ) {
			if ( isset( $group_fields[ $key ] ) && $limit[1] > 0 ) {
				$fields[ $group ][ $key ]['maxlength'] = $limit[1];
			}
		}
	}
	return $fields;
}

function perfectpixel_length_limits_validate() {
	$checkout_fields = WC()->checkout()->get_checkout_fields();

	foreach ( perfectpixel_length_limits() as $key => $limit ) {
		$value = isset( $_POST[ $key ] ) ? trim( wp_unslash( $_POST[ $key ] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification, WordPress.Security.ValidatedSanitizedInput
		if ( '' === $value ) {
			continue; // Required/empty checks are handled by WooCommerce.
		}

		$label = $key;
		foreach ( $checkout_fields as $group_fields ) {
			if ( ! empty( $group_fields[ $key ]['label'] ) ) {
				$label = wp_strip_all_tags( $group_fields[ $key ]['label'] );
			}
		}

		$length = mb_strlen( $value );
		if ( $limit[0] > 0 && $length < $limit[0] ) {
			wc_add_notice( sprintf( esc_html( '{{min_length_error}}' ), '<strong>' . esc_html( $label ) . '</strong>', $limit[0] ), 'error' );
		} elseif ( $limit[1] > 0 && $length > $limit[1] ) {
			wc_add_notice( sprintf( esc_html( '{{max_length_error}}' ), '<strong>' . esc_html( $label ) . '</strong>', $limit[1] ), 'error' );
		}
	}
}
